input.command:
$s='C:\Users\3D6B~1\AppData\Local\Temp\claude\C--visual-projects-game\b7459343-774d-4e44-ba07-6ab779435a7e\scratchpad'
New-Item -ItemType Directory -Force $s | Out-Null
@'
const {spawn}=require('child_process');
const p=spawn('npx.cmd',['-y','@coding-solo/godot-mcp@0.1.1'],{env:{...process.env,GODOT_PATH:process.argv[2]},shell:true});
let buf='';const out=[];
p.stdout.on('data',d=>{buf+=d;let i;while((i=buf.indexOf('\n'))>=0){const l=buf.slice(0,i);buf=buf.slice(i+1);try{out.push(JSON.parse(l))}catch{}}});
p.stderr.on('data',d=>process.stderr.write(d));
const send=o=>p.stdin.write(JSON.stringify(o)+'\n');
send({jsonrpc:'2.0',id:1,method:'initialize',params:{protocolVersion:'2024-11-05',capabilities:{},clientInfo:{name:'t',version:'1'}}});
setTimeout(()=>{send({jsonrpc:'2.0',method:'notifications/initialized'});send({jsonrpc:'2.0',id:2,method:'tools/list'});},15000);
setTimeout(()=>{send({jsonrpc:'2.0',id:3,method:'tools/call',params:{name:'get_godot_version',arguments:{}}});},20000);
setTimeout(()=>{const t=out.find(o=>o.id===2);console.log(out.find(o=>o.id===1)?.result?.serverInfo, t?.result?.tools?.length, t?.result?.tools?.map(x=>x.name).join(','));console.log(JSON.stringify(out.find(o=>o.id===3)));p.kill();process.exit()},30000);
'@ | Set-Content "$s\t.js" -Encoding utf8
node "$s\t.js" "C:\Users\Георгий\AppData\Local\Microsoft\WinGet\Links\godot.exe" 2>&1 | Select-Object -Last 15
Get-Content "C:\visual projects\game\.mcp.json"

